import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import { jobsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const Jobs = () => {
  const { currentUser } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedJob, setSelectedJob] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      const response = await jobsAPI.getJobs();
      setJobs(response.data);
    } catch (err) {
      setError('Failed to load jobs');
    } finally {
      setLoading(false);
    }
  };

  const applyForJob = async (jobId) => {
    try {
      setLoading(true);
      await jobsAPI.applyForJob(jobId);
      setSuccess('Successfully applied for the job!');
      setDialogOpen(false);
      // Refresh jobs to update application status
      fetchJobs();
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to apply for job');
    } finally {
      setLoading(false);
    }
  };

  const openJobDetails = (job) => {
    setSelectedJob(job);
    setDialogOpen(true);
  };

  const closeDialog = () => {
    setDialogOpen(false);
    setSelectedJob(null);
  };

  const getJobTypeColor = (jobType) => {
    switch (jobType) {
      case 'full-time': return 'primary';
      case 'part-time': return 'secondary';
      case 'contract': return 'success';
      case 'internship': return 'warning';
      default: return 'default';
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Job Opportunities
      </Typography>
      <Typography variant="body1" color="textSecondary" sx={{ mb: 3 }}>
        Browse and apply for jobs from our partner companies
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }}>
          {success}
        </Alert>
      )}

      <Grid container spacing={3}>
        {jobs.length === 0 ? (
          <Grid item xs={12}>
            <Paper elevation={3} sx={{ padding: 4, textAlign: 'center' }}>
              <Typography variant="h6" color="textSecondary">
                No jobs available at the moment
              </Typography>
              <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                Check back later for new job opportunities from our partner companies.
              </Typography>
            </Paper>
          </Grid>
        ) : (
          jobs.map((job) => (
            <Grid item xs={12} md={6} key={job.id}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    {job.title}
                  </Typography>
                  <Typography variant="body2" color="textSecondary" gutterBottom>
                    {job.company?.name} • {job.location}
                  </Typography>
                  <Typography variant="body2" paragraph>
                    {job.description.length > 150 
                      ? `${job.description.substring(0, 150)}...` 
                      : job.description
                    }
                  </Typography>
                  
                  <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
                    <Chip 
                      label={job.jobType} 
                      color={getJobTypeColor(job.jobType)}
                      size="small"
                    />
                    <Chip 
                      label={job.salary} 
                      variant="outlined"
                      size="small"
                    />
                  </Box>

                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button
                      variant="outlined"
                      onClick={() => openJobDetails(job)}
                      size="small"
                    >
                      View Details
                    </Button>
                    <Button
                      variant="contained"
                      onClick={() => applyForJob(job.id)}
                      disabled={loading}
                      size="small"
                    >
                      Apply Now
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))
        )}
      </Grid>

      {/* Job Details Dialog */}
      <Dialog open={dialogOpen} onClose={closeDialog} maxWidth="md" fullWidth>
        <DialogTitle>
          {selectedJob?.title}
        </DialogTitle>
        <DialogContent>
          {selectedJob && (
            <Box>
              <Typography variant="h6" gutterBottom>
                Company: {selectedJob.company?.name}
              </Typography>
              <Typography variant="body2" color="textSecondary" gutterBottom>
                Location: {selectedJob.location} • {selectedJob.jobType} • {selectedJob.salary}
              </Typography>
              
              <Typography variant="body1" paragraph sx={{ mt: 2 }}>
                {selectedJob.description}
              </Typography>

              <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>
                Requirements
              </Typography>
              {selectedJob.requirements && (
                <Box sx={{ mb: 2 }}>
                  {selectedJob.requirements.educationLevel && (
                    <Typography variant="body2">
                      <strong>Education:</strong> {selectedJob.requirements.educationLevel}
                    </Typography>
                  )}
                  {selectedJob.requirements.minExperience && (
                    <Typography variant="body2">
                      <strong>Experience:</strong> {selectedJob.requirements.minExperience} years
                    </Typography>
                  )}
                  {selectedJob.requirements.skills && selectedJob.requirements.skills.length > 0 && (
                    <Box sx={{ mt: 1 }}>
                      <Typography variant="body2">
                        <strong>Skills:</strong>
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                        {selectedJob.requirements.skills.map((skill, index) => (
                          <Chip key={index} label={skill} size="small" variant="outlined" />
                        ))}
                      </Box>
                    </Box>
                  )}
                </Box>
              )}

              <Typography variant="body2" color="textSecondary">
                <strong>Application Deadline:</strong> {new Date(selectedJob.deadline).toLocaleDateString()}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeDialog}>Close</Button>
          <Button 
            variant="contained" 
            onClick={() => applyForJob(selectedJob?.id)}
            disabled={loading}
          >
            Apply for this Job
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Jobs;
